import { Meta, StoryObj } from "@storybook/react";
import { ExpandContent, ExpandContentWithoutState, expandContentButtonTypes } from "./expand-content";
import { useState } from "react";
import { expect, userEvent, waitFor, within } from "storybook/test";
import { ShowcaseLayout, Variant, showcaseParameters } from "@/storybook/preview";

type StoryArgs = React.ComponentProps<typeof ExpandContent> & {
  isExpanded: boolean;
};

// ExpandContent is only a useState wrapper around ExpandContentWithoutState and always starts
// collapsed. Every story renders this wrapper instead: it takes the start state from args or
// from the variant (so snapshots can capture expanded content) but still owns the state, so the
// toggle button works in the showcases too.
const StatefulExpandContent = ({ isExpanded: initialIsExpanded, ...args }: StoryArgs) => {
  const [isExpanded, setIsExpanded] = useState(initialIsExpanded);
  return <ExpandContentWithoutState {...args} isExpanded={isExpanded} setIsExpanded={setIsExpanded} />;
};

const meta: Meta<StoryArgs> = {
  title: "Primitives/Expand Content",
  component: ExpandContent,
  // The global reset removes Storybook's story padding, so a focused toggle button at the edge of
  // the canvas gets its focus ring clipped. Give every story some room in all directions.
  decorators: [
    (Story) => (
      <div style={{ padding: "1rem" }}>
        <Story />
      </div>
    ),
  ],
  parameters: {
    docs: {
      description: {
        component:
          "Collapsible section with a toggle button that expands and collapses its children with an " +
          "animated height transition. The toggle labels default to the translated `readMore`/`readLess` " +
          "strings and the button comes in three styles (`regular`, `plain`, `ghost`).",
      },
    },
  },
  argTypes: {
    buttonType: { control: "select", options: expandContentButtonTypes },
    buttonPosition: { control: "radio", options: ["top", "bottom"] },
    rightContent: { table: { disable: true } },
    children: { table: { disable: true } },
    isExpanded: { table: { disable: true } },
  },
  args: {
    buttonType: "regular",
    buttonPosition: "bottom",
    showMoreLabelOverride: undefined,
    showLessLabelOverride: undefined,
    removeChildrenWhenUnexpanded: false,
    children: <div>This is the hidden content!</div>,
    isExpanded: false,
  },
  render: (args) => <StatefulExpandContent {...args} />,
};

export default meta;
type Story = StoryObj<StoryArgs>;

export const Default: Story = {};

export const VariantButtonTypes: Story = {
  parameters: showcaseParameters,
  render: ({ ...args }) => (
    <ShowcaseLayout title="buttonType" variantType="prop">
      {expandContentButtonTypes.map((buttonType) => (
        <Variant key={buttonType} label={buttonType}>
          <StatefulExpandContent {...args} buttonType={buttonType} isExpanded={false} />
        </Variant>
      ))}
    </ShowcaseLayout>
  ),
};

export const VariantLayout: Story = {
  parameters: showcaseParameters,
  render: ({ ...args }) => (
    <ShowcaseLayout title="Layout (mixed props)" variantType="other">
      <Variant label="expanded">
        <StatefulExpandContent {...args} isExpanded />
      </Variant>
      <Variant label="buttonPosition top">
        <StatefulExpandContent {...args} buttonPosition="top" isExpanded={false} />
      </Variant>
      <Variant label="rightContent">
        <StatefulExpandContent {...args} rightContent={<div>Right content</div>} isExpanded={false} />
      </Variant>
    </ShowcaseLayout>
  ),
};

export const TestToggle: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByTestId("expand-content-content-collapsed")).toBeInTheDocument();
    await userEvent.click(canvas.getByTestId("expand-content-toggle-button-collapsed"));
    await expect(canvas.getByText("This is the hidden content!")).toBeVisible();
    await userEvent.click(canvas.getByTestId("expand-content-toggle-button-expanded"));
    await expect(canvas.getByTestId("expand-content-content-collapsed")).toBeInTheDocument();
  },
};

/** With `removeChildrenWhenUnexpanded` the children leave the DOM while collapsed (so hidden links and
 * inputs cannot hijack the tab order) and are removed again once the collapse animation has finished. */
export const TestRemoveChildrenWhenUnexpanded: Story = {
  args: {
    removeChildrenWhenUnexpanded: true,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.queryByText("This is the hidden content!")).not.toBeInTheDocument();
    await userEvent.click(canvas.getByTestId("expand-content-toggle-button-collapsed"));
    await expect(canvas.getByText("This is the hidden content!")).toBeVisible();
    await userEvent.click(canvas.getByTestId("expand-content-toggle-button-expanded"));
    // The children stay mounted until the 200 ms collapse animation is done, so retry until gone.
    await waitFor(() => expect(canvas.queryByText("This is the hidden content!")).not.toBeInTheDocument());
  },
};
