import { PropsWithChildren, ReactNode, useEffect, useState } from "react";
import styles from "./expand-content.module.less";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { AnimatePresence, motion, usePresence } from "framer-motion";
import { useTranslation } from "react-i18next";
import { Icon } from "@/core/components/primitives/icon/icon";
import { exhaustiveCheck, multipleClassNames } from "../../../helpers";

export const expandContentButtonTypes = ["regular", "ghost", "plain"] as const;
type ButtonType = (typeof expandContentButtonTypes)[number];

type ExpandContentProps = {
  /** Replaces the translated `readMore` label */
  showMoreLabelOverride?: string;
  /** Replaces the translated `readLess` label */
  showLessLabelOverride?: string;
  /** Where the button sits relative to the content. Default `bottom` */
  buttonPosition?: "top" | "bottom";
  /** Toggle button style. Default `regular` */
  buttonType?: ButtonType;
  /** Rendered to the right of the toggle button */
  rightContent?: ReactNode;
  /** removeChildrenWhenUnexpanded can be useful when the children are links/inputs and would hijack tab order even when hidden */
  removeChildrenWhenUnexpanded?: boolean;
};

export const ExpandContent = ({ ...props }: PropsWithChildren<ExpandContentProps>) => {
  const [isExpanded, setIsExpanded] = useState(false);

  return <ExpandContentWithoutState {...props} isExpanded={isExpanded} setIsExpanded={setIsExpanded} />;
};

export type ExpandContentWithoutStateProps = ExpandContentProps & {
  isExpanded: boolean;
  setIsExpanded: (isExpanded: boolean) => void;
};
export const ExpandContentWithoutState = ({
  showMoreLabelOverride,
  showLessLabelOverride,
  buttonPosition = "bottom",
  buttonType = "regular",
  children,
  rightContent,
  removeChildrenWhenUnexpanded,
  isExpanded,
  setIsExpanded,
}: PropsWithChildren<ExpandContentWithoutStateProps>) => {
  const { t } = useTranslation();

  const defaultMoreLabel = t("readMore");
  const defaultLessLabel = t("readLess");

  const showMoreLabel = showMoreLabelOverride ?? defaultMoreLabel;
  const showLessLabel = showLessLabelOverride ?? defaultLessLabel;

  const button = (
    <Button
      buttonType={buttonType}
      isExpanded={isExpanded}
      showLessLabel={showLessLabel}
      showMoreLabel={showMoreLabel}
      toggleIsExpanded={() => setIsExpanded(!isExpanded)}
      rightContent={rightContent}
    />
  );

  return (
    <div>
      {buttonPosition === "top" && button}
      <Content
        isExpanded={isExpanded}
        buttonPosition={buttonPosition}
        removeChildrenWhenUnexpanded={removeChildrenWhenUnexpanded}
      >
        {children}
      </Content>
      {buttonPosition === "bottom" && button}
    </div>
  );
};

const Button = ({
  buttonType,
  isExpanded,
  showLessLabel,
  showMoreLabel,
  toggleIsExpanded,
  rightContent,
}: {
  buttonType: ButtonType;
  isExpanded: boolean;
  showLessLabel: string;
  showMoreLabel: string;
  toggleIsExpanded: () => void;
  rightContent?: ReactNode;
}) => {
  switch (buttonType) {
    case "regular":
      return (
        <div className={styles.buttonRow}>
          <PrimaryButton
            complementary={true}
            label={isExpanded ? showLessLabel : showMoreLabel}
            onClick={() => toggleIsExpanded()}
            iconRightNew={isExpanded ? "remove" : "add"}
            data-testid={`expand-content-toggle-button-${isExpanded ? "expanded" : "collapsed"}`}
          />
          {rightContent}
        </div>
      );
    case "plain":
    case "ghost":
      return (
        <button
          className={multipleClassNames(
            styles.buttonRow,
            styles.plainButton,
            buttonType === "ghost" && styles.ghostButton,
          )}
          onClick={() => toggleIsExpanded()}
          data-testid={`expand-content-toggle-button-${isExpanded ? "expanded" : "collapsed"}`}
        >
          <span className={styles.buttonContent}>
            <motion.span
              initial={{ rotate: isExpanded ? 180 : 0 }}
              animate={{ rotate: isExpanded ? 180 : 0 }}
              className={styles.iconWrapper}
            >
              <Icon name="expand-more" className={styles.icon} />
            </motion.span>
            <span className={styles.buttonLabel}>{isExpanded ? showLessLabel : showMoreLabel}</span>
          </span>
          {rightContent}
        </button>
      );
    default:
      return exhaustiveCheck(buttonType);
  }
};

const animationDuration = 0.2;

export const DisappearingChildren = ({ children }: PropsWithChildren) => {
  // This component is used to remove children after the animation has finished
  // Learn more: https://www.framer.com/motion/animate-presence/#usepresence
  const [isPresent, safeToRemove] = usePresence();
  useEffect(() => {
    !isPresent && setTimeout(safeToRemove, animationDuration * 1000);
  }, [isPresent, safeToRemove]);

  return <>{children}</>;
};

export const Content = ({
  isExpanded,
  buttonPosition,
  removeChildrenWhenUnexpanded,
  children,
}: PropsWithChildren<{
  isExpanded: boolean;
  buttonPosition?: ExpandContentProps["buttonPosition"];
  removeChildrenWhenUnexpanded?: ExpandContentProps["removeChildrenWhenUnexpanded"];
}>) => {
  const [shouldOverflow, setShouldOverflow] = useState(false);
  return (
    <motion.div
      className={styles.expandContent}
      data-button-position={buttonPosition}
      initial={false}
      animate={{ height: isExpanded ? "auto" : 0, overflow: shouldOverflow ? "visible" : "hidden" }}
      transition={{ duration: animationDuration, type: "tween" }}
      onAnimationStart={(target: { height: "auto" | 0 }) => {
        //Starting to hide content, stop it from overflowing immediately
        if (target.height === 0) {
          setShouldOverflow(false);
        }
      }}
      onAnimationComplete={(target: { height: "auto" | 0 }) => {
        //It has finished expanding, let the content overflow
        if (target.height === "auto") {
          setShouldOverflow(true);
        }
      }}
      data-testid={`expand-content-content-${isExpanded ? "expanded" : "collapsed"}`}
    >
      {removeChildrenWhenUnexpanded ? (
        <AnimatePresence>{isExpanded && <DisappearingChildren>{children}</DisappearingChildren>}</AnimatePresence>
      ) : (
        children
      )}
    </motion.div>
  );
};
